#!/usr/bin/env bash
set -euo pipefail

# Drive one 3-season assembly ritual. With the default 60-second season this
# takes about 75 seconds, including the two assembly halves.

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"
DRY_RUN="${DRY_RUN:-0}"
ENV_FILE="$ROOT_DIR/scripts/.env.demo"

if [[ -f "$ENV_FILE" ]]; then
  # This file is generated by deploy-testnet.sh and contains only assignments.
  # shellcheck disable=SC1090
  source "$ENV_FILE"
elif [[ "$DRY_RUN" == "1" ]]; then
  CONTRACT="tide-demo.testnet"
  ana="ana-demo.testnet"
  ben="ben-demo.testnet"
  cy="cy-demo.testnet"
  dee="dee-demo.testnet"
  eve="eve-demo.testnet"
  greedy="greedy-demo.testnet"
  printf 'DRY_RUN: scripts/.env.demo is missing; using placeholder account ids.\n'
else
  printf 'Missing scripts/.env.demo. Run scripts/deploy-testnet.sh first.\n' >&2
  exit 1
fi

: "${CONTRACT:?CONTRACT is missing from scripts/.env.demo}"
: "${ana:?ana is missing from scripts/.env.demo}"
: "${ben:?ben is missing from scripts/.env.demo}"
: "${cy:?cy is missing from scripts/.env.demo}"
: "${dee:?dee is missing from scripts/.env.demo}"
: "${eve:?eve is missing from scripts/.env.demo}"
: "${greedy:?greedy is missing from scripts/.env.demo}"

HONEST=($ana $ben $cy $dee $eve)
ALL=($ana $ben $cy $dee $eve $greedy)
STAKE="5000000000000000000000000"

print_command() {
  printf '+ '
  printf '%q ' "$@"
  printf '\n'
}

tx() {
  local signer="$1" method="$2" args="$3" deposit="$4"
  local -a command=(near --quiet contract call-function as-transaction "$CONTRACT" "$method"
    json-args "$args" prepaid-gas "100 Tgas" attached-deposit "$deposit"
    sign-as "$signer" network-config testnet sign-with-legacy-keychain send)
  print_command "${command[@]}"
  if [[ "$DRY_RUN" == "1" ]]; then
    return 0
  fi
  "${command[@]}"
}

view() {
  local method="$1" args="$2"
  local -a command=(near --quiet contract call-function as-read-only "$CONTRACT" "$method"
    json-args "$args" network-config testnet now)
  print_command "${command[@]}"
  if [[ "$DRY_RUN" == "1" ]]; then
    printf '%s\n' '{}'
  else
    "${command[@]}"
  fi
}

json_value() {
  local field="$1"
  node -e '
    let raw = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", chunk => raw += chunk);
    process.stdin.on("end", () => {
      const starts = [];
      for (let i = 0; i < raw.length; i++) if (raw[i] === "{" || raw[i] === "[") starts.push(i);
      for (let i = starts.length - 1; i >= 0; i--) {
        try {
          const value = JSON.parse(raw.slice(starts[i]).trim());
          const path = process.argv[1].split(".");
          let current = value;
          for (const key of path) current = current[key];
          if (current !== undefined) { process.stdout.write(String(current)); return; }
        } catch (_) {}
      }
      process.exit(2);
    });
  ' "$field"
}

wait_for() {
  local target_season="$1" target_stage="${2:-}"
  if [[ "$DRY_RUN" == "1" ]]; then
    printf 'DRY_RUN: would wait for season %s%s\n' "$target_season" \
      "${target_stage:+, stage $target_stage}"
    return
  fi
  while :; do
    local raw season stage
    raw="$(view get_sea '{}')"
    season="$(printf '%s' "$raw" | json_value season)"
    stage="$(printf '%s' "$raw" | json_value assembly 2>/dev/null || true)"
    if (( season >= target_season )) && { [[ -z "$target_stage" ]] || [[ "$stage" == "$target_stage" ]]; }; then
      printf 'Reached season %s%s\n' "$season" "${stage:+, stage $stage}"
      return
    fi
    sleep 2
  done
}

fair_effort() {
  local account="$1" raw
  raw="$(view get_boat "{\"account_id\":\"${account}\"}")"
  printf '%s' "$raw" | node -e '
    let raw = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", chunk => raw += chunk);
    process.stdin.on("end", () => {
      const starts = [];
      for (let i = 0; i < raw.length; i++) if (raw[i] === "{") starts.push(i);
      for (let i = starts.length - 1; i >= 0; i--) {
        try {
          const v = JSON.parse(raw.slice(starts[i]).trim());
          const effort = BigInt(v.fair_share) * 10000n / BigInt(v.full_effort_catch);
          process.stdout.write(String(effort < 1n ? 1n : effort > 10000n ? 10000n : effort));
          return;
        } catch (_) {}
      }
      process.exit(2);
    });
  '
}

printf '\n=== SEASON 0: BUILD SIX BOATS ===\n'
for boat in "${ALL[@]}"; do
  tx "$boat" stake "{\"amount\":\"$STAKE\"}" "0 NEAR"
done

wait_for 1
printf '\n=== SEASON 1: FAIR FISHING AND OVERFISHING ===\n'
for boat in "${HONEST[@]}"; do
  if [[ "$DRY_RUN" == "1" ]]; then
    effort=3344
    printf 'DRY_RUN: fair effort for %s would be read from get_boat (using %s)\n' "$boat" "$effort"
  else
    effort="$(fair_effort "$boat")"
  fi
  tx "$boat" fish "{\"effort_bps\":$effort}" "0 NEAR"
done
tx "$greedy" fish '{"effort_bps":10000}' "0 NEAR"
printf '%s\n' 'Indictments for cycle 0:'
view get_indictments '{"cycle":0}'

wait_for 2 hold
printf '\n=== SEASON 2, HOLD: VOTE TO HOLD AN OSTRACISM ===\n'
for boat in "${HONEST[@]}"; do
  tx "$boat" vote_hold '{"yes":true}' "0 NEAR"
done
tx "$greedy" vote_hold '{"yes":false}' "0 NEAR"

wait_for 2 shards
printf '\n=== SEASON 2, SHARDS: NAME THE OVERFISHER ===\n'
for boat in "${HONEST[@]:0:3}"; do
  tx "$boat" write_shard "{\"names\":[\"$greedy\"]}" "0 NEAR"
done

wait_for 3
printf '\n=== SEASON 3: SETTLE THE ASSEMBLY ===\n'
tx "$ana" tick '{}' "0 NEAR"
printf '%s\n' 'Assembly:'
view get_assembly '{}'
printf '%s\n' 'Exiles:'
view get_exiles '{}'

printf '\n=== EXILE CHECK: FISH AND TRANSFER MUST FAIL ===\n'
for method in fish ft_transfer; do
  if [[ "$method" == "ft_transfer" ]]; then
    args="{\"receiver_id\":\"$ana\",\"amount\":\"1\",\"memo\":null}"
  else
    args='{"effort_bps":10000}'
  fi
  set +e
  if [[ "$DRY_RUN" == "1" ]]; then
    if [[ "$method" == "ft_transfer" ]]; then
      tx "$greedy" "$method" "$args" "1 yoctoNEAR"
    else
      tx "$greedy" "$method" "$args" "0 NEAR"
    fi
    status=1
    output='EXILED until season 13 (dry run)'
  else
    if [[ "$method" == "ft_transfer" ]]; then
      output="$(tx "$greedy" "$method" "$args" "1 yoctoNEAR" 2>&1)"
    else
      output="$(tx "$greedy" "$method" "$args" "0 NEAR" 2>&1)"
    fi
    status=$?
  fi
  set -e
  printf '%s\n' "$output"
  if (( status == 0 )) || [[ "$output" != *'EXILED until season 13'* ]]; then
    printf '%s did not fail with the expected exile error.\n' "$method" >&2
    exit 1
  fi
  printf 'Expected error: EXILED until season 13\n'
done

printf '\nDEMO COMPLETE\n'
